namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string CourseCode { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    Task<IReadOnlyList<Department>> GetDepartmentsAsync();
    Task<Department?> GetDepartmentAsync(int id);
    Task<IReadOnlyList<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null);
    Task<IReadOnlyList<Course>> GetFeaturedCoursesAsync();
    Task<Course?> GetCourseAsync(int id);
    Task SubmitEnrollmentRequestAsync(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public InMemoryCatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", CourseCode = "CS101", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, object-oriented design, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and has published extensively on programming education.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", CourseCode = "CS201", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park's research focuses on algorithm optimization and competitive programming. He has coached multiple ICPC teams.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, Title = "Database Systems", CourseCode = "CS305", Description = "Design and implementation of database systems. Covers relational model, SQL, normalization, transactions, and distributed databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked at Oracle for a decade before joining academia. She specializes in distributed database architectures.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, Title = "Calculus I", CourseCode = "MATH101", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Wright", InstructorBio = "Dr. Wright is an award-winning educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", CourseCode = "MATH202", Description = "Vector spaces, linear transformations, matrices, eigenvalues, and applications to data science and machine learning.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Lisa Kim", InstructorBio = "Dr. Kim bridges mathematics and machine learning, contributing to both theoretical research and practical applications.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 6, Title = "Classical Mechanics", CourseCode = "PHYS201", Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, and rigid body dynamics.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Robert Hughes", InstructorBio = "Dr. Hughes is a theoretical physicist whose research spans classical and quantum mechanics.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 7, Title = "Quantum Physics", CourseCode = "PHYS301", Description = "Introduction to quantum mechanics: wave-particle duality, Schrödinger equation, operators, and applications to atomic physics.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Emily Novak", InstructorBio = "Dr. Novak is a quantum computing researcher who brings cutting-edge science into the classroom.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
            new() { Id = 8, Title = "Creative Writing", CourseCode = "ENG210", Description = "Workshop-based course in fiction and poetry. Students produce and critique original works in multiple genres.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Prof. David Okafor", InstructorBio = "Prof. Okafor is a published novelist and poet whose work has been featured in major literary journals.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new() { Id = 9, Title = "American Literature", CourseCode = "ENG301", Description = "Survey of American literature from the colonial period to the present, with emphasis on major authors and literary movements.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Dr. Rachel Adams", InstructorBio = "Dr. Adams specializes in 20th-century American fiction and has written several critical studies on modernist writers.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new() { Id = 10, Title = "World History: 1500 to Present", CourseCode = "HIST102", Description = "Global history from the Age of Exploration to modern globalization. Examines cultural exchange, conflict, and social change.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an expert in global history with fieldwork experience across three continents.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true },
        };
    }

    public Task<IReadOnlyList<Department>> GetDepartmentsAsync()
        => Task.FromResult<IReadOnlyList<Department>>(_departments);

    public Task<Department?> GetDepartmentAsync(int id)
        => Task.FromResult(_departments.FirstOrDefault(d => d.Id == id));

    public Task<IReadOnlyList<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null)
    {
        IEnumerable<Course> results = _courses;

        if (departmentId.HasValue)
            results = results.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            results = results.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return Task.FromResult<IReadOnlyList<Course>>(results.ToList());
    }

    public Task<IReadOnlyList<Course>> GetFeaturedCoursesAsync()
        => Task.FromResult<IReadOnlyList<Course>>(_courses.Where(c => c.IsFeatured).ToList());

    public Task<Course?> GetCourseAsync(int id)
        => Task.FromResult(_courses.FirstOrDefault(c => c.Id == id));

    public Task SubmitEnrollmentRequestAsync(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return Task.CompletedTask;
    }
}

