@page "/"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p class="lead">Explore our departments and courses. Find the right classes for your academic journey.</p>
        <a href="/courses" class="btn btn-primary btn-lg">Browse All Courses</a>
    </div>

    <section class="mt-5">
        <h2>Featured Courses</h2>
        <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mt-2">
            @if (_featuredCourses is not null)
            {
                @foreach (var course in _featuredCourses)
                {
                    <div class="col">
                        <div class="card h-100">
                            <div class="card-body">
                                <h5 class="card-title">@course.Title</h5>
                                <h6 class="card-subtitle mb-2 text-muted">@course.CourseCode &middot; @course.Credits credits</h6>
                                <p class="card-text">@course.Description[..Math.Min(course.Description.Length, 120)]...</p>
                            </div>
                            <div class="card-footer">
                                <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                            </div>
                        </div>
                    </div>
                }
            }
        </div>
    </section>

    <section class="mt-5">
        <h2>Departments</h2>
        <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mt-2">
            @if (_departments is not null)
            {
                @foreach (var dept in _departments)
                {
                    <div class="col">
                        <div class="card h-100">
                            <div class="card-body">
                                <h5 class="card-title">@dept.Name</h5>
                                <p class="card-text">@dept.Description</p>
                            </div>
                            <div class="card-footer">
                                <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">View Courses</a>
                            </div>
                        </div>
                    </div>
                }
            }
        </div>
    </section>
</div>

@code {
    private IReadOnlyList<UniversityCourseCatalog.Models.Course>? _featuredCourses;
    private IReadOnlyList<UniversityCourseCatalog.Models.Department>? _departments;

    protected override async Task OnInitializedAsync()
    {
        _featuredCourses = await CatalogService.GetFeaturedCoursesAsync();
        _departments = await CatalogService.GetDepartmentsAsync();
    }
}

@page "/courses"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<div class="container">
    <h1>Course Catalog</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
                   @bind="SearchTerm" @bind:event="oninput" @bind:after="FilterCoursesAsync" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="SelectedDepartmentId" @bind:after="FilterCoursesAsync">
                <option value="0">All Departments</option>
                @if (_departments is not null)
                {
                    @foreach (var dept in _departments)
                    {
                        <option value="@dept.Id">@dept.Name</option>
                    }
                }
            </select>
        </div>
    </div>

    @if (_courses is null)
    {
        <p>Loading courses...</p>
    }
    else if (_courses.Count == 0)
    {
        <p class="text-muted">No courses found matching your criteria.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in _courses)
                    {
                        <tr>
                            <td>@course.CourseCode</td>
                            <td>@course.Title</td>
                            <td>@course.DepartmentName</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private string SearchTerm { get; set; } = string.Empty;
    private int SelectedDepartmentId { get; set; }
    private IReadOnlyList<UniversityCourseCatalog.Models.Course>? _courses;
    private IReadOnlyList<UniversityCourseCatalog.Models.Department>? _departments;

    protected override async Task OnInitializedAsync()
    {
        _departments = await CatalogService.GetDepartmentsAsync();
        await FilterCoursesAsync();
    }

    private async Task FilterCoursesAsync()
    {
        int? deptId = SelectedDepartmentId > 0 ? SelectedDepartmentId : null;
        var search = string.IsNullOrWhiteSpace(SearchTerm) ? null : SearchTerm;
        _courses = await CatalogService.GetCoursesAsync(search, deptId);
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>
    <p class="text-muted">Submit your enrollment request below. You will be notified by email once it is processed.</p>

    @if (_submitted)
    {
        <div class="alert alert-success" role="alert">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Your enrollment request has been received. You will be notified of the outcome.</p>
            <hr>
            <a href="/courses" class="btn btn-outline-success">Back to Courses</a>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-8 col-lg-6">
                <EditForm Model="Model" OnValidSubmit="HandleSubmitAsync" FormName="EnrollmentForm" method="post">
                    <DataAnnotationsValidator />
                    <AntiforgeryToken />
                    <ValidationSummary class="text-danger" />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                        <ValidationMessage For="() => Model.StudentName" class="text-danger" />
                    </div>

                    <div class="mb-3">
