                    </div>

                    <div class="mb-3">
                        <label for="courseSelect" class="form-label">Course</label>
                        <InputSelect id="courseSelect" class="form-select" @bind-Value="Model.CourseId">
                            <option value="0">-- Select a course --</option>
                            @if (_courses is not null)
                            {
                                @foreach (var course in _courses)
                                {
                                    <option value="@course.Id">@course.CourseCode – @course.Title</option>
                                }
                            }
                        </InputSelect>
                        <ValidationMessage For="() => Model.CourseId" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Request</button>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    private int? CourseId { get; set; }

    private IReadOnlyList<UniversityCourseCatalog.Models.Course>? _courses;
    private bool _submitted;

    protected override async Task OnInitializedAsync()
    {
        _courses = await CatalogService.GetCoursesAsync();
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private async Task HandleSubmitAsync()
    {
        await CatalogService.SubmitEnrollmentRequestAsync(Model);
        _submitted = true;
    }
}

